use xiom.io;

use xiom.string;
type Event = {
  event_type: Str;
  user_id: Int;
}

type Analytics = {
  events: Vec[Event];
  user_names: Map[Int, Str];
}

fn Analytics.new() -> Analytics {
  return Analytics{ events: Vec[Event].new(), user_names: Map[Int, Str].new() };
}

fn Analytics.record_event(a: &mut Analytics, event_type: Str, user_id: Int) {
  let e = Event{ event_type: event_type, user_id: user_id };
  a.events.push(e);
}

fn Analytics.get_user_name(a: &Analytics, id: Int) -> Str {
  return match a.user_names.get(&id) { Some(name) => name, None => "Unknown" };
}

fn main() -> Int {
  var a: Analytics = Analytics.new();
  a.user_names.insert(1, "Alice");
  a.record_event(&mut a, "click", 1);
  a.record_event(&mut a, "view", 1);

  io.println(a.get_user_name(&a, 1));
  io.println(to_string(a.events.len()));
  return 0;
}
